import { Project } from '../../src'
import { Diagnostic, path, GUID } from '@servicenow/sdk-build-core'

describe('Bidirectional Sync Test Suite', () => {
    test('Simple sync with no changes', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: GUID() },
        })

        const id = project.registerExplicitId('test_table', 'test')
        const content = `import { Record } from '@servicenow/sdk/core'

const hello = 'HELLO!'
Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Test',
        other: hello,
    },
})
`

        const index = project.addFile({ path: 'src/fluent/index.now.ts', content })

        {
            const diagnostics = (await index.getDiagnostics()) ?? []
            const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
            expect(errors).toHaveLength(0)

            const record = (await index.getRecords()).get('test_table', id)
            expect(record).toBeDefined()
            expect(record.getValue()).toStrictEqual({ name: 'Test', other: 'HELLO!' })
        }

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `
<?xml version="1.0"?>
<unload>
  <test_table action="INSERT_OR_UPDATE">
    <sys_id>${id}</sys_id>
    <name>Test</name>
    <other>HELLO!</other>
  </test_table>
</unload>
`,
        })

        expect(changedFiles).toHaveLength(0)

        {
            const diagnostics = (await index.getDiagnostics()) ?? []
            const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
            expect(errors).toHaveLength(0)

            const record = (await index.getRecords()).get('test_table', id)
            expect(record).toBeDefined()
            expect(record.getValue()).toStrictEqual({ name: 'Test', other: 'HELLO!' })
            expect(index.getContent()).toEqual(content)
        }
    })
    test('Simple sync which updates a record', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: GUID() },
        })

        const id = project.registerExplicitId('test_table', 'test')

        const index = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'

const hello = 'HELLO!'
Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Test',
        other: hello,
    },
})
`,
        })

        {
            const diagnostics = (await index.getDiagnostics()) ?? []
            const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
            expect(errors).toHaveLength(0)

            const record = (await index.getRecords()).get('test_table', id)
            expect(record).toBeDefined()
            expect(record.getValue()).toStrictEqual({ name: 'Test', other: 'HELLO!' })
        }

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `
<?xml version="1.0"?>
<unload>
  <test_table action="INSERT_OR_UPDATE">
    <sys_id>${id}</sys_id>
    <name>Changed!</name>
    <other>HELLO!</other>
    <new_prop>123</new_prop>
  </test_table>
</unload>
`,
        })

        expect(changedFiles).toHaveLength(1)

        {
            const diagnostics = (await index.getDiagnostics()) ?? []
            const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
            expect(errors).toHaveLength(0)

            const record = (await index.getRecords()).get('test_table', id)
            expect(record).toBeDefined()
            expect(record.getValue()).toStrictEqual({
                name: 'Changed!',
                other: 'HELLO!',
                new_prop: '123',
            })
            expect(index.getContent()).toEqual(`import { Record } from '@servicenow/sdk/core'

const hello = 'HELLO!'
Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Changed!',
        other: hello,
        new_prop: '123',
    },
})
`)
        }
    })
    test('Sync maintains existing node types, if possible', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: GUID() },
        })

        const id = project.registerExplicitId('test_table', 'test')

        const index = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        numberAsString: '123',
        booleanAsString1: 'true',
        booleanAsString2: 'false',
        actualNumber: 456,
        actualBoolean: true
    },
})
`,
        })

        {
            const diagnostics = (await index.getDiagnostics()) ?? []
            const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
            expect(errors).toHaveLength(0)

            const records = (await index.getRecords()).query()
            expect(records).toHaveLength(1)
        }

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `
<?xml version="1.0"?>
<unload>
  <test_table action="INSERT_OR_UPDATE">
    <sys_id>${id}</sys_id>
    <numberAsString>234</numberAsString>
    <booleanAsString1>false</booleanAsString1>
    <booleanAsString2>true</booleanAsString2>
    <actualNumber>567</actualNumber>
    <actualBoolean>false</actualBoolean>
  </test_table>
</unload>
`,
        })

        expect(changedFiles).toHaveLength(1)

        {
            const diagnostics = (await index.getDiagnostics()) ?? []
            const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
            expect(errors).toHaveLength(0)

            const record = (await index.getRecords()).get('test_table', id)
            expect(record).toBeDefined()
            expect(record.getValue()).toStrictEqual({
                numberAsString: '234',
                booleanAsString1: 'false',
                booleanAsString2: 'true',
                actualNumber: 567,
                actualBoolean: false,
            })
            expect(index.getContent()).toEqual(`import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        numberAsString: '234',
        booleanAsString1: 'false',
        booleanAsString2: 'true',
        actualNumber: 567,
        actualBoolean: false,
    },
})
`)
        }
    })
    test('Simple sync which creates a new record', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: GUID() },
        })

        const content = `import { Record } from '@servicenow/sdk/core'

const hello = 'HELLO!'
Record({
    $id: Now.ID['existing'],
    table: 'test_table',
    data: {
        name: 'Test',
        other: hello,
    },
})
`

        const index = project.addFile({ path: 'src/fluent/index.now.ts', content })

        {
            const diagnostics = (await index.getDiagnostics()) ?? []
            const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
            expect(errors).toHaveLength(0)

            const [record] = (await index.getRecords()).query('test_table')
            expect(record).toBeDefined()
            expect(record.getValue()).toStrictEqual({ name: 'Test', other: 'HELLO!' })
        }

        const id = GUID()
        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `
<?xml version="1.0"?>
<unload>
  <test_table action="INSERT_OR_UPDATE">
    <sys_id>${id}</sys_id>
    <name>New</name>
    <other>HELLO!</other>
    <new_prop>123</new_prop>
  </test_table>
</unload>
`,
        })

        expect(changedFiles).toHaveLength(1)

        {
            const diagnostics = (await index.getDiagnostics()) ?? []
            const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
            expect(errors).toHaveLength(0)

            const [record] = (await index.getRecords()).query('test_table')
            expect(record).toBeDefined()
            expect(record.getValue()).toStrictEqual({ name: 'Test', other: 'HELLO!' }) // Unchanged
            expect(index.getContent()).toEqual(content) // Unchanged
        }

        const newFile = changedFiles[0]
        expect(newFile).toBeDefined()
        expect(newFile.getPath()).toBe(
            path.join(project.getRootDir(), 'src', 'fluent', 'generated', 'other', 'test-table', `changes.now.ts`)
        )

        {
            const diagnostics = (await newFile.getDiagnostics()) ?? []
            const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
            expect(errors).toHaveLength(0)

            const record = (await newFile.getRecords()).get('test_table', id)
            expect(record).toBeDefined()
            expect(record.getValue()).toStrictEqual({
                name: 'New',
                other: 'HELLO!',
                // string '123' because we don't coerce new incoming properties
                new_prop: '123',
            })
            expect(newFile.getContent()).toEqual(`import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['${id}'],
    table: 'test_table',
    data: {
        name: 'New',
        other: 'HELLO!',
        new_prop: '123',
    },
})
`)
        }
    })
    test('Simple sync which deletes a record', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: GUID() },
        })

        const id = project.registerExplicitId('test_table', 'test')

        const index = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'

const hello = 'HELLO!'
Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Test',
        other: hello,
    },
})
`,
        })

        {
            const diagnostics = (await index.getDiagnostics()) ?? []
            const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
            expect(errors).toHaveLength(0)

            const record = (await index.getRecords()).get('test_table', id)
            expect(record).toBeDefined()
            expect(record.getValue()).toStrictEqual({ name: 'Test', other: 'HELLO!' })
        }

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `
<?xml version="1.0"?>
<unload>
  <test_table action="DELETE">
    <sys_id>${id}</sys_id>
    <name>Changed!</name>
    <other>HELLO!</other>
    <new_prop>123</new_prop>
  </test_table>
</unload>
`,
        })

        expect(changedFiles).toHaveLength(1)

        {
            const diagnostics = (await index.getDiagnostics()) ?? []
            const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
            expect(errors).toHaveLength(0)

            const records = (await index.getRecords()).query()
            expect(records).toHaveLength(0)
            expect(index.getContent()).toEqual('')
        }
    })
})
